const cursor_ts = msg.metadata.source.timestamp;
const utils = global.get("utils");
const connection = msg.metadata.connection_name;
const source = msg.metadata.source.identifier;


// Filter conditions
msg.payload = msg.payload.filter(entry => {
    if (new Date(entry.createdAt).getTime() <= cursor_ts) return false;
    if (entry.content && utils.is_bridge_message(entry.content)) return false;
    if (entry.username && utils.is_bridge_message(entry.username)) return false;
    return true;
});

if (msg.payload.length === 0) return null;

// Update timestamp
global.set(
    `parat_bridge.connections.${connection}.clients.${source}.timestamp`,
    new Date(msg.payload[msg.payload.length - 1].createdAt).getTime()
);

return msg;

// Sort messages oldest-first so the filter advances the cursor correctly
if (!msg.payload || msg.payload.length === 0) return null;

msg.payload.sort((a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime());
return msg;

if (msg.mapImage) {
    const file = {
        name: msg.mapImage.name,
        type: msg.mapImage.type,
        size: msg.mapImage.buffer.length,
        _buffer: msg.mapImage.buffer
    };

    msg.payload.files = (msg.payload.files || []).concat(file);
    delete msg.mapImage;
}

// Extract description and coordinates from GeoJSON
const geo = JSON.parse(msg.payload.content);
const [lng, lat] = geo.geometry.coordinates;
const description = geo.properties.description || "";
const mapsLink = "Klikk her for å åpne i Google Maps:\nhttps://www.google.com/maps?q=" + lat + "%2C" + lng;
msg.payload.content = description ? description + "\n\n" + mapsLink : mapsLink;

delete msg.isLocation;

return msg;
